-- User-facing label: "Ülke hakkında". Summaries contain stable cultural and
-- geographic context, not visa advice or current travel-safety recommendations.
-- UPDATE only: destinations previously removed from an existing DB stay removed.
-- Cover the full ISO seed as well so fresh installations have no empty summaries.
ALTER TABLE countries ADD COLUMN summary VARCHAR(600);

UPDATE countries SET summary = 'Pirene Dağları arasında yer alan Andorra, taş köyleri, Romanesk kiliseleri ve dağ manzaralarıyla tanınır. Katalan kültürü, küçük yerleşimlerin günlük yaşamında belirgin bir yer tutar.' WHERE iso_code = 'AD';
UPDATE countries SET summary = 'Birleşik Arap Emirlikleri, Dubai ve Abu Dabi’nin modern kent dokusunu çöl manzaraları ve Körfez kıyılarıyla bir araya getirir. Geleneksel çarşılar ve denizcilik mirası, çağdaş mimarinin yanında yaşamaya devam eder.' WHERE iso_code = 'AE';
UPDATE countries SET summary = 'Afganistan’ın dağlık coğrafyasında Hindukuş sıraları, geniş vadiler ve eski ticaret yollarının izleri bulunur. Bamyan ve Herat gibi yerler, bölgenin köklü sanat ve mimarlık mirasını yansıtır.' WHERE iso_code = 'AF';
UPDATE countries SET summary = 'Antigua ve Barbuda, Karayipler’de koyları, kumsalları ve yelken kültürüyle tanınan iki ana adadan oluşur. Antigua’daki tarihî liman yapıları, adaların denizcilik geçmişini günümüze taşır.' WHERE iso_code = 'AG';
UPDATE countries SET summary = 'Anguilla, Karayipler’de açık renkli kumsalları ve alçak kıyı yerleşimleriyle öne çıkar. Ada yaşamında deniz ürünleri, tekne yapımı ve yerel müzik gelenekleri önemli bir yer tutar.' WHERE iso_code = 'AI';
UPDATE countries SET summary = 'Arnavutluk, Adriyatik ve İyon kıyılarından dağlık iç bölgelere uzanan farklı manzaralar sunar. Berat ve Gjirokastra’nın tarihî mahalleleri, taş evleri ve Osmanlı dönemi mimarisiyle tanınır.' WHERE iso_code = 'AL';
UPDATE countries SET summary = 'Ermenistan, Güney Kafkasya’da yüksek platoları, taş manastırları ve dağ gölleriyle tanınır. Erivan’ın kent kültürü ve geleneksel mutfak, ülkenin köklü tarihinin günlük yaşamdaki yansımalarıdır.' WHERE iso_code = 'AM';
UPDATE countries SET summary = 'Angola’nın Atlas Okyanusu kıyıları, geniş akarsu havzaları ve iç kesimlerdeki yüksek düzlükleri farklı doğal görünümler oluşturur. Luanda’nın kent yaşamında Portekizce konuşulan Afrika’nın müzik ve mutfak mirası hissedilir.' WHERE iso_code = 'AO';
UPDATE countries SET summary = 'Antarktika, geniş buz örtüsü, buzdağları ve sert kutup coğrafyasıyla şekillenen bir kıtadır. Kıyı ekosistemlerinde penguenler, foklar ve deniz kuşları bulunurken insan varlığı ağırlıkla araştırma istasyonları çevresinde toplanır.' WHERE iso_code = 'AQ';
UPDATE countries SET summary = 'Arjantin, Buenos Aires’in tango kültüründen Patagonya’nın bozkır ve buzullarına kadar uzanan geniş bir coğrafyaya sahiptir. And Dağları, bağ bölgeleri ve geleneksel mate kültürü ülkenin farklı yüzlerini oluşturur.' WHERE iso_code = 'AR';
UPDATE countries SET summary = 'Amerikan Samoası, Güney Pasifik’te volkanik adaları, tropik kıyıları ve Polinezya kültürüyle tanınır. Pago Pago çevresindeki doğal liman ve geleneksel köy yaşamı, bölgenin karakterini belirler.' WHERE iso_code = 'AS';
UPDATE countries SET summary = 'Avusturya, Alp manzaralarını Viyana ve Salzburg’un müzik ve mimarlık mirasıyla buluşturur. Göller, dağ kasabaları ve tarihî kent merkezleri ülkenin coğrafi ve kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'AT';
UPDATE countries SET summary = 'Avustralya, geniş iç bölgeleri, Büyük Set Resifi ve birbirinden farklı kıyı kentleriyle tanınır. Aborjin ve Torres Boğazı Adalı halklarının kültürleri, kıtanın çok katmanlı mirasının temel parçalarıdır.' WHERE iso_code = 'AU';
UPDATE countries SET summary = 'Aruba, Karayipler’in güneyinde kuru iklimli iç kesimleri ve açık renkli sahilleriyle öne çıkar. Oranjestad’ın renkli yapıları ve yerel dil Papiamento, adanın farklı kültürel etkilerini yansıtır.' WHERE iso_code = 'AW';
UPDATE countries SET summary = 'Åland Adaları, Baltık Denizi’nde kayalık kıyılar, küçük limanlar ve denizcilik geleneğiyle şekillenen bir takımadadır. İsveççe konuşulan ada yaşamı, tarihî yelkenliler ve kıyı köyleri çevresinde gelişmiştir.' WHERE iso_code = 'AX';
UPDATE countries SET summary = 'Azerbaycan, Hazar Denizi kıyılarını Kafkas dağları ve tarihî ticaret yollarıyla birleştirir. Bakü’nün sur içi yerleşimi, çağdaş mimarisi ve geleneksel mutfak bu çeşitliliğin belirgin örnekleridir.' WHERE iso_code = 'AZ';
UPDATE countries SET summary = 'Bosna-Hersek, dağlar ve nehir vadileri arasında Osmanlı ve Avusturya-Macaristan dönemlerinden izler taşır. Saraybosna’nın çarşıları ve Mostar’ın taş köprüsü, ülkenin zengin kent mirasını temsil eder.' WHERE iso_code = 'BA';
UPDATE countries SET summary = 'Barbados, Karayipler’in doğusunda mercan kökenli kıyıları ve Atlantik’e bakan manzaralarıyla tanınır. Bridgetown’un tarihî yapıları, kriket geleneği ve yerel müzik ada kültürünün parçalarıdır.' WHERE iso_code = 'BB';
UPDATE countries SET summary = 'Bangladeş, Ganj ve Brahmaputra nehirlerinin oluşturduğu geniş delta üzerinde şekillenir. Nehir yaşamı, Dakka’nın hareketli sokakları ve Sundarbanlar’ın mangrov ormanları ülkenin farklı yüzlerini gösterir.' WHERE iso_code = 'BD';
UPDATE countries SET summary = 'Belçika, Brüksel’in çok kültürlü kent yaşamını Brugge ve Gent’in tarihî sokaklarıyla birleştirir. Çikolata, çizgi roman ve güçlü mimarlık gelenekleri ülkenin kültürel kimliğinde belirgin yer tutar.' WHERE iso_code = 'BE';
UPDATE countries SET summary = 'Burkina Faso, Batı Afrika’da Sahel kuşağı ile savanların buluştuğu bir coğrafyada yer alır. Yerel el sanatları, maske gelenekleri ve Bobo-Dioulasso’nun kent mirası kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'BF';
UPDATE countries SET summary = 'Bulgaristan, Karadeniz kıyılarından Balkan ve Rodop dağlarına uzanan farklı manzaralara sahiptir. Filibe’nin tarihî mahalleleri, manastırlar ve halk müziği ülkenin zengin mirasını tamamlar.' WHERE iso_code = 'BG';
UPDATE countries SET summary = 'Bahreyn, Basra Körfezi’nde inci avcılığı ve deniz ticareti geçmişiyle şekillenmiş bir ada ülkesidir. Manama’nın modern yapıları, geleneksel çarşılar ve eski yerleşim kalıntılarıyla yan yana durur.' WHERE iso_code = 'BH';
UPDATE countries SET summary = 'Burundi, Büyük Göller bölgesinde tepeleri ve Tanganika Gölü kıyılarıyla tanınır. Davul geleneği, dans ve tarımsal köy yaşamı ülkenin kültürel dokusunda önemli bir yer tutar.' WHERE iso_code = 'BI';
UPDATE countries SET summary = 'Benin, Batı Afrika’nın Atlas Okyanusu kıyısında eski krallıkların ve kıyı ticaretinin izlerini taşır. Abomey sarayları, geleneksel el sanatları ve yerel inanç gelenekleri kültürel mirasının parçalarıdır.' WHERE iso_code = 'BJ';
UPDATE countries SET summary = 'Saint Barthelemy, Karayipler’de küçük koyları, tepelik iç kesimleri ve Gustavia limanıyla tanınır. Fransız ve ada kültürlerinin izleri, yerleşimlerin mimarisinde ve mutfağında görülür.' WHERE iso_code = 'BL';
UPDATE countries SET summary = 'Bermuda, Kuzey Atlantik’te pembe tonlu kumsalları, kireçtaşı mağaraları ve renkli evleriyle tanınan bir takımadadır. Denizcilik geçmişi ve Britanya etkileri, ada kültürünün belirgin unsurlarıdır.' WHERE iso_code = 'BM';
UPDATE countries SET summary = 'Brunei, Borneo Adası’nda yağmur ormanları ve geleneksel Malay kültürüyle şekillenir. Bandar Seri Begavan’daki camiler ve su üzerindeki Kampong Ayer yerleşimi, ülkenin en tanınan görünümlerindendir.' WHERE iso_code = 'BN';
UPDATE countries SET summary = 'Bolivya, And Dağları’nın yüksek platolarını Amazon havzasının alçak bölgeleriyle bir araya getirir. Uyuni tuz düzlükleri ve Titikaka çevresindeki Aymara ve Keçuva kültürleri ülkenin çeşitliliğini yansıtır.' WHERE iso_code = 'BO';
UPDATE countries SET summary = 'Karayip Hollandası, Bonaire, Sint Eustatius ve Saba adalarından oluşur. Mercan kıyıları, volkanik yükseltiler ve farklı yerleşim geçmişleri, bu üç adaya birbirinden ayrı karakterler kazandırır.' WHERE iso_code = 'BQ';
UPDATE countries SET summary = 'Brezilya, Amazon ormanlarından Atlantik kıyılarına ve büyük kentlere uzanan geniş bir coğrafyaya sahiptir. Yerli, Afrika ve Portekiz miraslarının etkileri müzikte, mutfakta ve günlük yaşamda görülür.' WHERE iso_code = 'BR';
UPDATE countries SET summary = 'Bahamalar, Atlantik’te sığ turkuaz suları, kum adaları ve deniz yaşamıyla tanınan bir takımadadır. Nassau’nun tarihî sokakları ve yerel Junkanoo geleneği ada kültürünün belirgin parçalarıdır.' WHERE iso_code = 'BS';
UPDATE countries SET summary = 'Butan, Himalayalar’da yüksek dağlar, ormanlık vadiler ve Budist manastırlarıyla tanınır. Kale-manastır yapıları, yerel festivaller ve geleneksel mimari ülkenin kültürel görünümünü oluşturur.' WHERE iso_code = 'BT';
UPDATE countries SET summary = 'Bouvet Adası, Güney Atlantik’te buzullarla kaplı uzak bir volkanik adadır. Dik kıyıları ve çevresindeki soğuk denizler, penguen ve fokların bulunduğu kutup ekosisteminin parçalarıdır.' WHERE iso_code = 'BV';
UPDATE countries SET summary = 'Botsvana’nın doğal görünümünü Okavango Deltası’nın sulak alanları ve Kalahari’nin kurak düzlükleri belirler. Geleneksel sepet örücülüğü ve farklı toplulukların kültürel mirası ülkenin kimliğini tamamlar.' WHERE iso_code = 'BW';
UPDATE countries SET summary = 'Belarus, geniş ormanları, gölleri ve düz arazileriyle tanınır. Minsk’in kent dokusu, tarihî kaleler ve geleneksel keten işçiliği ülkenin farklı dönemlerden kalan mirasını yansıtır.' WHERE iso_code = 'BY';
UPDATE countries SET summary = 'Belize, Orta Amerika’nın Karayip kıyısında mercan resifleri, tropik ormanlar ve Maya yerleşimleriyle tanınır. Farklı toplulukların dilleri ve mutfakları, ülkenin kültürel çeşitliliğini gösterir.' WHERE iso_code = 'BZ';
UPDATE countries SET summary = 'Kanada, geniş ormanları, Büyük Göller’i ve Kayalık Dağlar’ıyla çok farklı doğal bölgelere sahiptir. Yerli halkların mirası, Fransızca ve İngilizce konuşulan kentlerin kültürel yaşamıyla birlikte ülkenin kimliğini oluşturur.' WHERE iso_code = 'CA';
UPDATE countries SET summary = 'Cocos Adaları, Hint Okyanusu’nda lagünler ve hindistancevizi ağaçlarıyla çevrili mercan adalarından oluşur. Cocos Malay kültürü ve denizle kurulan yakın ilişki, yerel yaşamın belirgin özellikleridir.' WHERE iso_code = 'CC';
UPDATE countries SET summary = 'Demokratik Kongo Cumhuriyeti, Kongo Nehri havzasındaki geniş yağmur ormanları ve çok çeşitli doğal yaşamıyla tanınır. Kinşasa’nın müzik geleneği ve farklı toplulukların sanatı, ülkenin zengin kültürel mirasını yansıtır.' WHERE iso_code = 'CD';
UPDATE countries SET summary = 'Orta Afrika Cumhuriyeti, savanlar, akarsular ve Kongo havzasına uzanan tropik ormanlar arasında yer alır. Ahşap işçiliği, müzik ve farklı toplulukların sözlü gelenekleri kültürel mirasını oluşturur.' WHERE iso_code = 'CF';
UPDATE countries SET summary = 'Kongo Cumhuriyeti, Atlas Okyanusu kıyısından Kongo havzasının yağmur ormanlarına uzanır. Brazzavil’in kent kültürü, nehir yaşamı ve yerel müzik gelenekleri ülkenin farklı yönlerini yansıtır.' WHERE iso_code = 'CG';
UPDATE countries SET summary = 'İsviçre, Alpler’in dağ manzaraları, gölleri ve tarihî kentleriyle tanınır. Farklı dil bölgeleri, geleneksel peynir üretimi ve güçlü tasarım geleneği kültürel çeşitliliğinin parçalarıdır.' WHERE iso_code = 'CH';
UPDATE countries SET summary = 'Fildişi Sahili, Gine Körfezi kıyılarından ormanlık iç bölgelere ve savanlara uzanır. Abidjan’ın kent yaşamı, Grand-Bassam’ın tarihî yapıları ve kakao kültürü ülkenin karakterini yansıtır.' WHERE iso_code = 'CI';
UPDATE countries SET summary = 'Cook Adaları, Güney Pasifik’te volkanik adalar ve mercan atollerini bir araya getirir. Rarotonga’nın dağlık görünümü, Aitutaki lagünü ve Polinezya dans gelenekleri bu çeşitliliğin örnekleridir.' WHERE iso_code = 'CK';
UPDATE countries SET summary = 'Şili, And Dağları ile Pasifik arasında uzanan uzun kıyı coğrafyasıyla tanınır. Atacama Çölü, bağ vadileri ve Patagonya’nın buzulları ülkenin birbirinden farklı doğal bölgelerini oluşturur.' WHERE iso_code = 'CL';
UPDATE countries SET summary = 'Kamerun, Atlantik kıyıları, volkanik dağlar, yağmur ormanları ve savanları aynı coğrafyada buluşturur. Farklı toplulukların müzik, el sanatı ve mutfak gelenekleri ülkenin kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'CM';
UPDATE countries SET summary = 'Çin, eski ticaret yollarından büyük metropollere uzanan geniş bir tarih ve coğrafya çeşitliliğine sahiptir. Çin Seddi, klasik bahçeler, bölgesel mutfaklar ve geleneksel sanatlar bu mirasın farklı yüzleridir.' WHERE iso_code = 'CN';
UPDATE countries SET summary = 'Kolombiya, And Dağları’nı Karayip ve Pasifik kıyılarıyla bir araya getirir. Kahve bölgeleri, Cartagena’nın tarihî merkezi ve farklı yerel müzikler ülkenin canlı kültürel dokusunu yansıtır.' WHERE iso_code = 'CO';
UPDATE countries SET summary = 'Kosta Rika, Pasifik ve Karayip kıyıları arasında yağmur ormanları, volkanlar ve zengin doğal yaşamıyla tanınır. Kahve yetiştiriciliği ve doğayla iç içe yerleşimler ülkenin günlük yaşamında belirgindir.' WHERE iso_code = 'CR';
UPDATE countries SET summary = 'Küba, Karayipler’de tarihî kentleri, tütün kültürü ve güçlü müzik geleneğiyle tanınır. Havana’nın meydanları, farklı dönemlerden mimarisi ve Afro-Küba ritimleri adanın kültürel görünümünü oluşturur.' WHERE iso_code = 'CU';
UPDATE countries SET summary = 'Cabo Verde, Batı Afrika açıklarında volkanik adalar ve Atlantik kıyılarıyla şekillenir. Kreol kültürü, morna müziği ve adalar arasında değişen doğal manzaralar ülkenin karakterini belirler.' WHERE iso_code = 'CV';
UPDATE countries SET summary = 'Curaçao, Karayipler’de renkli Willemstad evleri ve koylarla parçalanmış kıyılarıyla tanınır. Papiamento dili, Hollanda mimarlık mirası ve farklı toplulukların mutfağı ada kültüründe bir araya gelir.' WHERE iso_code = 'CW';
UPDATE countries SET summary = 'Christmas Adası, Hint Okyanusu’nda tropik ormanlar, dik kıyılar ve kireçtaşı oluşumlarıyla tanınır. Kırmızı yengeçlerin mevsimsel göçü, adanın en belirgin doğa olaylarından biridir.' WHERE iso_code = 'CX';
UPDATE countries SET summary = 'Kıbrıs, Doğu Akdeniz’de antik yerleşimler, taş köyler ve deniz kıyılarıyla katmanlı bir kültürel miras taşır. Trodos Dağları ve bölgesel mutfak, adanın kıyıların ötesindeki çeşitliliğini gösterir.' WHERE iso_code = 'CY';
UPDATE countries SET summary = 'Çekya, Prag’ın tarihî kent dokusundan Bohemya ve Moravya’nın kasaba ve kırsal manzaralarına uzanır. Kaleler, cam işçiliği ve köklü müzik geleneği ülkenin kültürel kimliğinde belirgindir.' WHERE iso_code = 'CZ';
UPDATE countries SET summary = 'Almanya, tarihî kentlerini modern sanat, tasarım ve sanayi kültürüyle birleştirir. Berlin’in müzelerinden Ren vadisine, ormanlardan Alp eteklerine uzanan coğrafyası farklı bölgesel karakterler taşır.' WHERE iso_code = 'DE';
UPDATE countries SET summary = 'Cibuti, Kızıldeniz ile Aden Körfezi’nin buluştuğu çevrede volkanik arazileri ve tuz gölleriyle tanınır. Assal Gölü ve Afar ile Somali kültürlerinin etkileri ülkenin doğal ve kültürel görünümünü belirler.' WHERE iso_code = 'DJ';
UPDATE countries SET summary = 'Danimarka, kıyı kasabalarını bisiklet kültürü, çağdaş tasarım ve tarihî liman kentleriyle buluşturur. Kopenhag’ın renkli kıyıları ve Viking döneminden izler ülkenin farklı yüzlerini gösterir.' WHERE iso_code = 'DK';
UPDATE countries SET summary = 'Dominika, Karayipler’de volkanik dağları, yoğun yağmur ormanları ve akarsularıyla tanınır. Kalinago mirası, yerel bitki kültürü ve Creole gelenekleri ada yaşamının önemli parçalarıdır.' WHERE iso_code = 'DM';
UPDATE countries SET summary = 'Dominik Cumhuriyeti, Hispanyola Adası’nın doğusunda kumsalları, dağlık iç bölgeleri ve sömürge dönemi kent mirasıyla tanınır. Merengue ve bachata, günlük yaşamın belirgin müzik gelenekleridir.' WHERE iso_code = 'DO';
UPDATE countries SET summary = 'Cezayir, Akdeniz kıyılarından Sahra’nın geniş çöl coğrafyasına uzanır. Roma dönemi kalıntıları, eski kent mahalleleri ve Amazig kültürünün izleri ülkenin köklü mirasını oluşturur.' WHERE iso_code = 'DZ';
UPDATE countries SET summary = 'Ekvador, And Dağları, Amazon havzası, Pasifik kıyıları ve Galápagos Adaları’yla farklı doğal dünyaları bir araya getirir. Quito’nun tarihî merkezi ve yerel pazarlar kültürel mirasının önemli parçalarıdır.' WHERE iso_code = 'EC';
UPDATE countries SET summary = 'Estonya, Baltık kıyıları, ormanları ve adalarıyla sakin doğal manzaralara sahiptir. Tallinn’in Orta Çağ sokakları ve güçlü koro geleneği, çağdaş kent kültürüyle yan yana yaşar.' WHERE iso_code = 'EE';
