UPDATE countries SET summary = 'Batı Sahra, Atlantik kıyıları ile Sahra’nın kum ve taşlık düzlükleri arasında uzanır. Sahra halklarının göçebe mirası, sözlü kültürü ve denizle bağlantılı yerleşimleri bölgenin kültürel dokusunu oluşturur.' WHERE iso_code = 'EH';
