UPDATE countries SET summary = 'Etiyopya, yüksek yaylaları, Rift Vadisi ve köklü tarihî yerleşimleriyle tanınır. Kayaya oyulmuş kiliseler, kahve kültürü ve farklı dil topluluklarının gelenekleri ülkenin zengin mirasını oluşturur.' WHERE iso_code = 'ET';
