UPDATE countries SET summary = 'Mikronezya, Pasifik’in geniş bir alanına yayılan adalarında lagünleri ve denizcilik geleneklerini bir araya getirir. Taş yapılar, sözlü tarih ve yerel el sanatları adalar arasında değişen kültürleri yansıtır.' WHERE iso_code = 'FM';
UPDATE countries SET summary = 'Faroe Adaları, Kuzey Atlantik’te dik yamaçları, deniz kayalıkları ve çimen çatılı evleriyle tanınır. Balıkçılık, örgü ve yerel müzik gelenekleri, okyanusla şekillenen ada kültürünün parçalarıdır.' WHERE iso_code = 'FO';
UPDATE countries SET summary = 'Fransa, Paris’in sanat ve mimarlık mirasını birbirinden farklı kırsal ve kıyı bölgeleriyle birleştirir. Bölgesel mutfaklar, tarihî kasabalar ve Alp manzaraları ülkenin kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'FR';
UPDATE countries SET summary = 'Gabon, Atlas Okyanusu kıyıları ve geniş tropik ormanlarıyla tanınır. Kıyı lagünleri, orman ekosistemleri ve geleneksel ahşap işçiliği ülkenin doğal ve kültürel zenginliğini oluşturur.' WHERE iso_code = 'GA';
