UPDATE countries SET summary = 'Tuvalu, Pasifik’te alçak mercan adaları, lagünler ve okyanusla iç içe yerleşimleriyle tanınır. Geleneksel denizcilik, topluluk dansları ve yerel el sanatları ada kültürünün önemli parçalarıdır.' WHERE iso_code = 'TV';
