UPDATE countries SET summary = 'Tanzanya, savanlarını Kilimanjaro’nun dağlık coğrafyası ve Hint Okyanusu kıyılarıyla buluşturur. Zanzibar’ın tarihî kent dokusu ve Svahili kültürü, ülkenin farklı miraslarını yansıtır.' WHERE iso_code = 'TZ';
UPDATE countries SET summary = 'Ukrayna, geniş düzlükleri, Karpat manzaraları ve köklü kent mirasıyla tanınır. Geleneksel nakış, halk müziği ve bölgesel mutfaklar ülkenin kültürel kimliğinde önemli bir yer tutar.' WHERE iso_code = 'UA';
UPDATE countries SET summary = 'Uganda, Büyük Göller bölgesinde gölleri, tropik ormanları ve yüksek kesimleriyle tanınır. Nil havzasındaki yaşam ve farklı toplulukların müzik, dans ve el sanatları ülkenin kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'UG';
UPDATE countries SET summary = 'ABD Küçük Harici Adaları, Pasifik ve Karayip çevresindeki uzak ada ve mercan oluşumlarını kapsar. Çoğunda öne çıkan özellik, deniz kuşları ve mercan ekosistemleriyle şekillenen doğal çevredir.' WHERE iso_code = 'UM';
UPDATE countries SET summary = 'Amerika Birleşik Devletleri, büyük metropollerinden çöller, dağlar ve farklı kıyı bölgelerine uzanan geniş bir coğrafyaya sahiptir. Yerli halkların mirası ve göçlerle şekillenen kültürler ülkenin çeşitliliğini oluşturur.' WHERE iso_code = 'US';
UPDATE countries SET summary = 'Uruguay, Atlantik kıyıları, geniş otlakları ve nehir çevresindeki yerleşimleriyle tanınır. Montevideo’nun kent yaşamı, candombe ritimleri ve mate geleneği ülkenin kültürel kimliğinin parçalarıdır.' WHERE iso_code = 'UY';
UPDATE countries SET summary = 'Özbekistan, Semerkant, Buhara ve Hive gibi tarihî İpek Yolu kentleriyle tanınır. Çini işçiliği, anıtsal mimari ve geleneksel dokumalar ülkenin zengin kültürel mirasını yansıtır.' WHERE iso_code = 'UZ';
UPDATE countries SET summary = 'Vatikan, Roma’nın içinde Aziz Petrus Meydanı, bazilikası ve geniş sanat koleksiyonlarıyla tanınır. Sistina Şapeli ve Rönesans eserleri, küçük devletin dinî ve sanatsal mirasının belirgin parçalarıdır.' WHERE iso_code = 'VA';
UPDATE countries SET summary = 'Saint Vincent ve Grenadinler, Karayipler’de volkanik dağları, küçük adaları ve kıyı koylarıyla tanınır. Denizcilik, yerel müzik ve ada topluluklarının gelenekleri takımadanın kültürel karakterini oluşturur.' WHERE iso_code = 'VC';
UPDATE countries SET summary = 'Venezuela, Karayip kıyılarını And Dağları, geniş düzlükler ve yüksek masa dağlarıyla buluşturur. Angel Şelalesi ve farklı toplulukların müzik ve mutfak gelenekleri ülkenin çeşitliliğini yansıtır.' WHERE iso_code = 'VE';
UPDATE countries SET summary = 'Britanya Virjin Adaları, Karayipler’de koyları, mercan kıyıları ve küçük limanlarıyla tanınır. Denizcilik geçmişi, yerel müzik ve farklı ada topluluklarının yaşamı kültürel dokusunu oluşturur.' WHERE iso_code = 'VG';
UPDATE countries SET summary = 'ABD Virjin Adaları, Karayipler’de kıyı koyları, tropik bitki örtüsü ve tarihî liman yerleşimleriyle tanınır. Afrika, Avrupa ve ada kültürlerinin izleri mimaride, mutfakta ve müzikte bir araya gelir.' WHERE iso_code = 'VI';
UPDATE countries SET summary = 'Vietnam, pirinç tarımıyla şekillenen kırsal bölgelerini dağlar, deltalar ve uzun kıyı şeridiyle birleştirir. Hanoi’nin tarihî sokakları, geleneksel el sanatları ve bölgesel mutfaklar ülkenin kültürel çeşitliliğini yansıtır.' WHERE iso_code = 'VN';
UPDATE countries SET summary = 'Vanuatu, Güney Pasifik’te volkanik adaları, tropik ormanları ve kıyı yerleşimleriyle tanınır. Farklı yerel diller, geleneksel topluluk yaşamı ve denizle bağlantılı kültürel miras adalar arasında çeşitlilik gösterir.' WHERE iso_code = 'VU';
UPDATE countries SET summary = 'Wallis ve Futuna, Güney Pasifik’te volkanik adalar, mercan kıyıları ve küçük yerleşimlerden oluşur. Polinezya gelenekleri, yerel diller ve topluluk yaşamı adaların kültürel kimliğini oluşturur.' WHERE iso_code = 'WF';
UPDATE countries SET summary = 'Samoa, Güney Pasifik’te volkanik adaları, yağmur ormanları ve kıyı köyleriyle tanınır. Fa’a Samoa olarak anılan topluluk gelenekleri, mimaride, törenlerde ve günlük yaşamda belirgin yer tutar.' WHERE iso_code = 'WS';
UPDATE countries SET summary = 'Yemen, dağlık yerleşimlerini Kızıldeniz ve Arap Denizi kıyılarıyla birleştirir. Eski kentlerin toprak mimarisi, köklü ticaret yolları ve Sokotra’nın kendine özgü doğası ülkenin zengin mirasını yansıtır.' WHERE iso_code = 'YE';
UPDATE countries SET summary = 'Mayotte, Hint Okyanusu’nda volkanik adaları, geniş lagünü ve mercan ekosistemleriyle tanınır. Afrika, Madagaskar ve ada kültürlerinin etkileri yerel dillerde, mutfakta ve geleneklerde görülür.' WHERE iso_code = 'YT';
UPDATE countries SET summary = 'Güney Afrika, iki okyanusa uzanan kıyıları, dağları ve savanlarıyla farklı doğal bölgeleri bir araya getirir. Çok sayıda dil ve topluluğun mirası, kent kültüründe, müzikte ve mutfakta görülür.' WHERE iso_code = 'ZA';
UPDATE countries SET summary = 'Zambiya, büyük nehirleri, geniş doğal alanları ve Victoria Şelaleleri’yle tanınır. Farklı toplulukların el sanatları, müzikleri ve kırsal yaşam gelenekleri ülkenin kültürel kimliğini oluşturur.' WHERE iso_code = 'ZM';
UPDATE countries SET summary = 'Zimbabve, yüksek düzlükleri, büyük akarsuları ve tarihî taş yapılarıyla tanınır. Büyük Zimbabve kalıntıları, geleneksel heykel sanatı ve farklı toplulukların kültürleri ülkenin köklü mirasını yansıtır.' WHERE iso_code = 'ZW';

ALTER TABLE countries ALTER COLUMN summary SET NOT NULL;
ALTER TABLE countries ADD CONSTRAINT ck_country_summary_not_blank
    CHECK (CHAR_LENGTH(TRIM(summary)) > 0);
